"use strict";

// OpenClaw Hook：invoice-inbound
// 起因（2026-08-24 教練親口糾正）：「之前報了好幾筆發票資訊給小龍蝦，結果統計時竟然漏掉」。
// 查證真相（state/inbound_echo/2026-08-24.jsonl + 教練貼回的 LINE 對話）：
//   2026-08-20 10:51 教練說「記一下會員的發票資訊，給mac執行開發票」，
//   小龍蝦連續兩次回「⚠️ Agent couldn't generate a response」（context overflow 自動重啟），
//   接著教練陸續傳的 4 筆載具（連皓宇/陳新典/玫萱/吳三貴）就這樣沒被寫進知識檔，
//   直到 8/24 00:59 教練反問「我傳了這麼多筆你都沒記住？」才補登（第七批）。
//
// 根因不是小龍蝦「不用心」，是「落地這件事綁在 agent turn 上」——agent 掛了資料就沒了。
// 這支 hook 走 message:preprocessed（agent 還沒開始處理前），偵測到發票資訊當下就同步寫死到
// state/invoice_inbox/，不管後面 agent 成功/失敗/重啟，這筆都已經在磁碟上。
// 設計理念完全比照 inbound-message-echo-log（2026-08-06 同款根因的成功前例）。
//
// 教練 2026-08-24 裁示併入本 hook 的判斷規則：「只要是給手機條碼的一律是二聯，以後都不用再問」

const fs = require('fs');
const path = require('path');
const https = require('https');

const HOME = process.env.HOME;
const INBOX_DIR = path.join(HOME, '.openclaw', 'workspace', 'state', 'invoice_inbox');
const DEBUG_LOG = path.join(HOME, '.openclaw', 'logs', 'invoice-inbound-debug.log');
const OPENCLAW_CONFIG_PATH = path.join(HOME, '.openclaw', 'openclaw.json');
const COACH_TELEGRAM_CHAT_ID = '6124913915';

// 台灣手機發票載具：斜線 + 7 碼（大寫英數，可含 . - +）
const CARRIER_RE = /\/[A-Z0-9.\-+]{7}(?![A-Z0-9.\-+])/g;
// 統一編號：8 碼數字（要求前後不是數字，避免誤抓電話/金額）
const TAXID_LABELLED_RE = /(?:統一?編號?|統編|VAT|tax\s*id)\s*[:：]?\s*(\d{8})(?!\d)/gi;
const TAXID_BARE_RE = /(?<!\d)(\d{8})(?!\d)/g;
// 觸發關鍵字：命中任一才進一步解析，避免把所有訊息都當發票。
// 🔴 2026-08-24 實測補強：教練 8/20 真正掉的那則是「連皓宇 /88ZMR73\n陳新典 /92HFLDY…」，
// 全文一個發票關鍵字都沒有，只有姓名＋載具。若只認關鍵字，這支 hook 會重演同一個漏接。
// 因此載具形狀（斜線+7碼）本身就視為觸發條件。
const TRIGGER_KEYWORD_RE = /發票|統編|統一編號|載具|條碼|二聯|三聯|抬頭|開票/;
const TRIGGER_CARRIER_RE = /\/[A-Z0-9.\-+]{7}(?![A-Z0-9.\-+])/;

function debugLog(msg) {
  try {
    fs.mkdirSync(path.dirname(DEBUG_LOG), { recursive: true });
    fs.appendFileSync(DEBUG_LOG, new Date().toISOString() + ' ' + msg + '\n');
  } catch (e) {}
}

function extractText(event) {
  const c = (event && event.context) || {};
  const cands = [
    c.body, c.bodyForAgent,
    event.text,
    c.text, c.content, c.prompt, c.input, c.transcript, c.userText, c.userMessage,
    (c.message && (typeof c.message === 'string' ? c.message : (c.message.text || c.message.content))),
  ];
  const pickLast = (arr) => {
    if (Array.isArray(arr) && arr.length) {
      const last = arr[arr.length - 1];
      if (typeof last === 'string') return last;
      if (last && typeof last === 'object') return last.text || last.content || '';
    }
    return '';
  };
  cands.push(pickLast(event.messages));
  cands.push(pickLast(c.messages));
  for (const v of cands) if (typeof v === 'string' && v.trim()) return v;
  return '';
}

function resolveChatId(event) {
  const ctx = (event && event.context) || {};
  const raw = String(
    ctx.senderId || ctx.conversationId || ctx.from || ctx.to ||
    event.from || event.senderId || ''
  );
  return raw.replace(/^(telegram|line|whatsapp|discord|sms):/i, '');
}

function resolveChannel(event) {
  const ctx = (event && event.context) || {};
  if (ctx.channelId) return String(ctx.channelId);
  const sessionKey = String(event.sessionKey || ctx.sessionKey || '');
  const parts = sessionKey.split(':');
  const agentIdx = parts.indexOf('agent');
  if (agentIdx >= 0 && parts[agentIdx + 2]) return parts[agentIdx + 2];
  return 'unknown';
}

// 從一行文字裡撈中文姓名。實測（2026-08-24 用教練 8/18~8/24 真實訊息跑過）發現：
// 純粹「抓 2~4 個中文字」會把「三聯式發」「票資訊」「宿易智能」這種碎片也當成姓名，
// 所以改成先把已知的公司名／發票術語／載具／統編從該行挖掉，剩下的才當姓名候選。
const NAME_STOPWORDS = new Set([
  '發票', '統編', '載具', '條碼', '二聯', '三聯', '抬頭', '開票', '公司', '有限',
  '資訊', '記錄', '培訓', '會員', '教練', '謝謝', '麻煩', '這是', '更新', '記一下',
  '統一', '編號', '聯式', '手機', '這位', '還有', '另外', '以及', '如下', '補充',
]);
// 只要含這些字就不可能是人名
const NAME_REJECT_RE = /公司|有限|股份|事務|工作室|企業社|商行|發票|統編|編號|載具|條碼|聯式|抬頭|資訊/;
// 中文虛詞：人名不會含這些字，用來濾掉「只要是給」「的一律是」這種句子碎片
const PARTICLE_RE = /[的是了都不在有和與也就要會能把被給從對向跟我你他這那們個很再又還沒麼嗎呢吧啊了以及並且但因所以如果]/;
// 發票語境常見詞彙，抓姓名前先從該行挖掉
const NOISE_RE = /三聯式發票資訊|二聯式發票資訊|三聯式|二聯式|公司抬頭|統一編號|手機條碼|發票資訊|要給您開|培訓發票|記一下|買受人|統編|載具|條碼|抬頭|發票|三聯|二聯|開票/g;

function guessNames(text, companies) {
  const found = [];
  for (const rawLine of text.split(/[\n\r]+/)) {
    const line = rawLine.trim();
    if (!line) continue;
    CARRIER_RE.lastIndex = 0;
    const hasCarrier = CARRIER_RE.test(line);
    CARRIER_RE.lastIndex = 0;
    const hasTaxId = /(?<!\d)\d{8}(?!\d)/.test(line);
    const hasKeyword = TRIGGER_KEYWORD_RE.test(line);
    // 姓名可能單獨出現在「杜亞洛 要給您開培訓發票」這種只有關鍵字的行，所以三種都收
    if (!hasCarrier && !hasTaxId && !hasKeyword) continue;

    // 挖掉雜訊：公司名 → 載具 → 數字 → 發票術語
    let cleaned = line;
    for (const c of companies) cleaned = cleaned.split(c).join(' ');
    cleaned = cleaned.replace(CARRIER_RE, ' ').replace(/\d+/g, ' ').replace(NOISE_RE, ' ');
    CARRIER_RE.lastIndex = 0;

    for (const cand of (cleaned.match(/[一-龥]{2,4}/g) || [])) {
      if (NAME_STOPWORDS.has(cand)) continue;
      if (NAME_REJECT_RE.test(cand)) continue;
      if (PARTICLE_RE.test(cand)) continue;
      if (companies.some((c) => c.includes(cand))) continue;
      if (!found.includes(cand)) found.push(cand);
    }
  }
  return found;
}

function parseInvoiceBits(text) {
  const carriers = [];
  let m;
  CARRIER_RE.lastIndex = 0;
  while ((m = CARRIER_RE.exec(text)) !== null) {
    if (!carriers.includes(m[0])) carriers.push(m[0]);
  }

  const taxIds = [];
  TAXID_LABELLED_RE.lastIndex = 0;
  while ((m = TAXID_LABELLED_RE.exec(text)) !== null) {
    if (!taxIds.includes(m[1])) taxIds.push(m[1]);
  }
  if (taxIds.length === 0 && /統編|統一編號|三聯|抬頭/.test(text)) {
    // 有三聯/抬頭語境但沒有「統編：」標籤時，才退而求其次抓裸 8 碼
    TAXID_BARE_RE.lastIndex = 0;
    while ((m = TAXID_BARE_RE.exec(text)) !== null) {
      if (!taxIds.includes(m[1])) taxIds.push(m[1]);
    }
  }

  // 公司抬頭
  const companies = [];
  const compRe = /(?:公司抬頭|抬頭|買受人)\s*[:：]?\s*([^\n\r\/，,]{2,40}?(?:有限公司|股份有限公司|company|事務所|工作室|企業社|商行))/gi;
  while ((m = compRe.exec(text)) !== null) {
    const v = m[1].trim();
    if (v && !companies.includes(v)) companies.push(v);
  }
  if (companies.length === 0) {
    const bare = text.match(/[一-龥A-Za-z0-9]{2,20}(?:股份有限公司|有限公司|事務所|企業社|商行)/g) || [];
    for (const v of bare) if (!companies.includes(v)) companies.push(v);
  }

  // 教練 2026-08-24 裁示：給手機條碼的一律二聯
  let type = null;
  if (/三聯/.test(text) || taxIds.length > 0) type = '三聯';
  else if (/二聯/.test(text) || carriers.length > 0) type = '二聯';

  return { carriers, taxIds, companies, type, names: guessNames(text, companies) };
}

function monthFile() {
  const d = new Date();
  const local = new Date(d.getTime() + (8 * 60 + d.getTimezoneOffset()) * 60000);
  const y = local.getFullYear();
  const mm = String(local.getMonth() + 1).padStart(2, '0');
  return path.join(INBOX_DIR, `${y}-${mm}.jsonl`);
}

function sendTelegram(text) {
  // 跑測試時不要真的騷擾教練（scripts/test_invoice_inbound_hook.js 會設這個環境變數）
  if (process.env.INVOICE_HOOK_TEST === '1') return;
  try {
    const cfg = JSON.parse(fs.readFileSync(OPENCLAW_CONFIG_PATH, 'utf-8'));
    const botToken = cfg && cfg.channels && cfg.channels.telegram
      && cfg.channels.telegram.accounts && cfg.channels.telegram.accounts.bot_main
      && cfg.channels.telegram.accounts.bot_main.botToken;
    if (!botToken) return;
    // 2026-08-25教練要求：跟小龍蝦(AI)自己講的話要分得清楚，統一加標籤
    const body = JSON.stringify({
      chat_id: COACH_TELEGRAM_CHAT_ID,
      text: '🤖【賈維斯自動通知】\n' + text,
      disable_notification: true, // 只是回執，不該把教練從睡夢中吵醒
    });
    const req = https.request({
      hostname: 'api.telegram.org',
      path: `/bot${botToken}/sendMessage`,
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body) },
      timeout: 8000,
    });
    req.on('error', () => {});
    req.on('timeout', () => req.destroy());
    req.write(body);
    req.end();
  } catch (e) {}
}

const handler = async (event) => {
  if (!event || typeof event !== 'object') return;
  if (event.type !== 'message' || event.action !== 'preprocessed') return;

  try {
    const text = extractText(event);
    if (!text) return;
    if (!TRIGGER_KEYWORD_RE.test(text) && !TRIGGER_CARRIER_RE.test(text)) return;

    const bits = parseInvoiceBits(text);
    // 沒撈到任何可用資訊（只是閒聊提到「發票」兩個字）就不記，避免雜訊
    if (bits.carriers.length === 0 && bits.taxIds.length === 0) return;

    fs.mkdirSync(INBOX_DIR, { recursive: true });

    const entry = {
      ts: Date.now(),
      iso: new Date().toISOString(),
      taipei: new Date(Date.now() + 8 * 3600 * 1000).toISOString().replace('T', ' ').slice(0, 19),
      channel: resolveChannel(event),
      chatId: resolveChatId(event),
      sessionKey: event.sessionKey || (event.context && event.context.sessionKey) || '',
      names: bits.names,
      carriers: bits.carriers,
      taxIds: bits.taxIds,
      companies: bits.companies,
      type: bits.type,
      reconciled: false, // 對帳腳本比對過知識檔後會標記
      raw: text.slice(0, 2000),
    };

    // 同步寫入：收到當下立刻落地，不等 agent turn 跑完（agent 就算 overflow 重啟也不會掉）
    fs.appendFileSync(monthFile(), JSON.stringify(entry) + '\n');

    // 立刻給教練一句回執，讓他當場知道「這筆有進系統」，不用事後再問「你記了沒」
    const parts = [];
    if (bits.names.length) parts.push(bits.names.join('、'));
    if (bits.carriers.length) parts.push('載具 ' + bits.carriers.join(' '));
    if (bits.taxIds.length) parts.push('統編 ' + bits.taxIds.join(' '));
    if (bits.companies.length) parts.push(bits.companies.join('、'));
    if (bits.type) parts.push(bits.type);
    sendTelegram('🧾 發票資訊已自動存檔（不靠對話記憶，掉不了）\n' + parts.join('｜')
      + '\n檔案：state/invoice_inbox/' + path.basename(monthFile()));
  } catch (err) {
    debugLog('ERROR ' + (err && err.message));
  }
};

module.exports = handler;
module.exports.default = handler;

